- memory: Read and write the board assistant's persistent memory store. Supports view (list a directory or read a file), create (write a new file), str_replace (edit text in a file), and delete. parameters: {"type": "object", "properties": {"command": {"type": "string", "enum": ["view", "create", "str_replace", "delete"], "description": "Operation to perform"}, "path": {"type": "string", "description": "Path inside /memories/"}, "file_text": {"type": "string", "description": "Content for create"}, "old_str": {"type": "string", "description": "Text to replace for str_replace"}, "new_str": {"type": "string", "description": "Replacement text for str_replace"}}, "required": ["command", "path"]}
